import { memo, useState } from 'react'

import Image from './image'

import { AdPreview, useAdsFeed } from '@/query/post/getAds'
import MySlider from './PostCards/MySlider'
import { useIsFr } from '@/hooks/use-is-fr'
import ReactPlayer from 'react-player'
import PostTypeFeaturedIcon from './PostCards/PostTypeFeaturedIcon'
import SpinLoading from '@/shared/spin-loading'
import { cn } from '@/lib/utils'

function AdsSliderMulti() {
  const { data: ads, isLoading } = useAdsFeed(8)
  const isFr = useIsFr()

  if (isLoading || !ads?.length) return null
  return (
    <MySlider
      isFr={isFr}
      data={ads}
      renderItem={(ad) => {
        return (
          <div className="flex flex-col gap-4 group my-2" key={ad.id}>
            <div className="relative aspect-8/6 overflow-hidden rounded-3xl shadow-lg shadow-black/30 transition-shadow">
              {renderPostMedia(ad)}
            </div>

            <a href={ad.link} target="_blank" rel="noopener noreferrer">
              <p className="text-center text-base  font-semibold text-neutral-800 dark:text-neutral-200 line-clamp-2">
                {ad.title}
              </p>
            </a>
          </div>
        )
      }}
      itemPerRow={4}
    />
  )
}

export default memo(AdsSliderMulti)

const renderPostMedia = (ad: AdPreview) => {
  if (ad.Video) {
    if (!ad.Video.includes('youtu')) {
      if (ad.Video.includes('instagram')) {
        return (
          <>
            <blockquote
              className="instagram-media w-full"
              data-instgrm-permalink={ad.Video}
              data-instgrm-version="14"
              style={{ margin: 'auto' }}
            />
            <script async src="https://www.instagram.com/embed.js"></script>
          </>
        )
      }
      return (
        <iframe
          src={ad.Video}
          width="100%"
          height="100%"
          allow="autoplay; encrypted-media; picture-in-picture"
          allowFullScreen
          style={{ borderRadius: '12px', border: 'none' }}
        />
      )
    }
    return <YoutubeAd ad={ad} />
  }

  return <AdImage ad={ad} />
}

const AdImage = ({ ad }: { ad: AdPreview }) => {
  if (ad.Video)
    return (
      <Image
        src={{
          src: `https://images2.fibladi.com/H400/${ad.image.split('.')[0]}.webp`,
        }}
        altReal={ad.title}
        className=""
        fill
      />
    )
  return (
    <a
      href={ad.link}
      target="_blank"
      rel="noopener noreferrer"
      className="group block h-full w-full z-40"
    >
      <Image
        src={{
          src: `https://images2.fibladi.com/H400/${ad.image.split('.')[0]}.webp`,
        }}
        altReal={ad.title}
        className=""
        fill
      />
      <div className="absolute inset-0 bg-black/25 opacity-0 transition-opacity group-hover:opacity-80" />
    </a>
  )
}

const YoutubeAd = ({ ad }: { ad: AdPreview }) => {
  const [isClicked, setIsClicked] = useState(false)
  const [isPlaying, setIsPlaying] = useState(false)
  return (
    <>
      <AdImage ad={ad} />
      {!isClicked && (
        <PostTypeFeaturedIcon
          onClick={() => setIsClicked(!isClicked)}
          className="absolute z-30  top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 hover:bg-accent-foreground rounded-full cursor-pointer"
          postType={'video'}
        />
      )}

      <div
        className={cn(
          'flex items-center justify-center absolute inset-0',
          !isPlaying && !isClicked ? 'opacity-0' : 'opacity-100',
        )}
      >
        <SpinLoading />
      </div>

      <ReactPlayer
        url={ad.Video}
        playing={isClicked}
        style={{
          opacity: isPlaying ? 1 : 0,
        }}
        className="z-20 absolute inset-0 bg-neutral-900 transition-opacity"
        width="100%"
        height="100%"
        onPlay={() => {
          setIsPlaying(true)
          setIsClicked(true)
        }}
        onPause={() => {
          setIsPlaying(false)
          setIsClicked(false)
        }}
        onStart={() => {
          setIsPlaying(true)
        }}
      />
      <div className="absolute inset-0 bg-black/25 opacity-0 transition-opacity group-hover:opacity-80" />
    </>
  )
}
